use serde::{Deserialize, Serialize};

use crate::{Item, User};

/// Individual signals. Percentages generated by the simulator fall in 0..=100.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct PreferenceProfile {
    pub item_budget_cents: u32,
    pub price_sensitivity_pct: u8,
    pub ad_receptiveness_pct: u8,
}

impl Default for PreferenceProfile {
    fn default() -> Self {
        Self {
            item_budget_cents: 10_000,
            price_sensitivity_pct: 50,
            ad_receptiveness_pct: 50,
        }
    }
}

/// Weights are relative. A zero weight disables its signal.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PreferenceWeights {
    pub category_affinity: u32,
    pub affordability: u32,
    pub item_variation: u32,
    pub ad_receptiveness: u32,
}

impl Default for PreferenceWeights {
    fn default() -> Self {
        Self {
            category_affinity: 5,
            affordability: 3,
            item_variation: 2,
            ad_receptiveness: 2,
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub enum ScoredItem<'a> {
    Organic(&'a Item),
    Ad(&'a Item),
}

/// Score an item in [0, 1] using a weighted mean of the applicable signals.
/// The score is for ranking and is not a probability. An all-zero weight set is neutral.
pub fn score_preference(
    user: &User,
    scored_item: ScoredItem<'_>,
    weights: PreferenceWeights,
) -> f64 {
    let (item, ad_weight) = match scored_item {
        ScoredItem::Organic(item) => (item, 0.0),
        ScoredItem::Ad(item) => (item, f64::from(weights.ad_receptiveness)),
    };
    let category = if user.preferred_category_ids.contains(&item.category_id) {
        1.0
    } else {
        0.0
    };
    let profile = user.preference;
    let affordability = if item.price_cents <= profile.item_budget_cents {
        1.0
    } else {
        let budget_ratio = f64::from(profile.item_budget_cents) / f64::from(item.price_cents);
        1.0 - fraction(profile.price_sensitivity_pct) * (1.0 - budget_ratio)
    };
    let category_weight = f64::from(weights.category_affinity);
    let price_weight = f64::from(weights.affordability);
    let variation_weight = f64::from(weights.item_variation);
    let total = category_weight + price_weight + variation_weight + ad_weight;
    if total == 0.0 {
        return 0.5;
    }

    let variation = item_variation(&user.id, &item.id);
    (category_weight * category
        + price_weight * affordability
        + variation_weight * variation
        + ad_weight * fraction(profile.ad_receptiveness_pct))
        / total
}

fn fraction(percent: u8) -> f64 {
    f64::from(percent.min(100)) / 100.0
}

fn item_variation(user_id: &str, item_id: &str) -> f64 {
    // FNV-1a followed by a 64-bit finalizer keeps nearby identifiers from clustering.
    let mut hash = 0xcbf29ce484222325_u64;
    for byte in user_id.bytes().chain([0]).chain(item_id.bytes()) {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash = (hash ^ (hash >> 33)).wrapping_mul(0xff51afd7ed558ccd);
    hash = (hash ^ (hash >> 33)).wrapping_mul(0xc4ceb9fe1a85ec53);
    let top_bits = (hash ^ (hash >> 33)) >> 11;
    top_bits as f64 / (1_u64 << 53) as f64
}
